create table public.service_concepts (concept_id uuid, code text, name text, description text, default_can_be_primary boolean, default_can_be_secondary boolean, default_pricing_unit text, icon text, sort_order integer, is_active boolean, created_by uuid, updated_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone, billing_family text, vehicle_class text, distance_chargeable boolean, service_category text generated always as (
CASE
    WHEN (billing_family = 'system'::text) THEN 'system'::text
    WHEN (default_can_be_primary AND default_can_be_secondary) THEN 'mixed'::text
    WHEN default_can_be_primary THEN 'primary'::text
    ELSE 'secondary'::text
END) stored, quantity_source text, auto_apply boolean, matrix_visible boolean, single_address boolean);
